WITH base AS (SELECT *, ROUND(budget, 1) AS budget_rounded, LENGTH(location) AS location_length FROM departments WHERE location IS NOT NULL), eligible AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.is_remote)), kept AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.job_title = 'Intern')) SELECT *, LAG(location_length, 1) OVER (PARTITION BY location, dept_name ORDER BY location_length ASC, id ASC) AS prev_location_length, SUM(location_length) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_location_length FROM kept;
